*
 * POST /admin/clients/{client_id}/bonus_system_transactions.json
 *
 * Examples:
 *
 *      insales.createBonusTransaction({
 *        token: '1234567890',
 *        url: 'shop-test.myinsales.ru',
 *        clientid: '2',
 *        bonustransaction: {
 *          "bonus_system_transaction": {
 *            "bonus_points": 100,
 *            "description": "compliment"
 *          }
 *        }
 *      }).then(response => {
 *        console.info(response.data);
 *      }).catch(err => {
 *        console.error(err);
 *      });
